import sys
import subprocess
import xml.etree.ElementTree as ET
import re

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    return root

def run_command(command):
    try:
        result = subprocess.run(command, shell=True, check=True, text=True, capture_output=True)
        output = result.stdout.strip()
        if not output:
            return None
        return int(output)
    except subprocess.CalledProcessError:
        return None
    except ValueError:
        return None

def evaluate_expression(expr, value):
    try:
        # Replace 'value' with the provided value and evaluate
        expr = expr.replace('value', str(value))
        result = eval(expr)
        if not isinstance(result, int):
            return None
        return result
    except:
        return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python program.py <xml_file>")
        sys.exit(1)

    xml_path = sys.argv[1]
    root = parse_xml(xml_path)

    for task in root.findall('task'):
        name = task.get('name')
        command = task.find('command').text
        expr = task.find('expr').text

        value = run_command(command)
        if value is None:
            print(f"{name}: error")
            continue

        result = evaluate_expression(expr, value)
        if result is None:
            print(f"{name}: error")
        else:
            print(f"{name}: {result}")

if __name__ == "__main__":
    main()
